-- ============================================================
-- Climate per offer spot: UV, air temperature, water temperature
-- ============================================================
-- Three tables:
--   climate_points       cache of monthly climate per 0.1-degree cell (lat10/lng10 =
--                        round(lat*10)/round(lng*10)). Filled by pnpm cli climate-stats,
--                        seeded here with the 123 cells fetched on 2026-10-12.
--   climate_port_points  hand-geocoded departure ports / tour start points
--                        (free text in departure_port -> coordinates). "A or B" = A.
--                        Add a row when the job logs an unknown port.
--   offer_climate_stats  one row per offer (offer_id = view offer_id) with the
--                        climate of its point; what the app should read.
--
-- Point per offer (point_basis), per Aaron 2026-10-12:
--   cruise -> departure_port, tour -> start_point (both via climate_port_points;
--   fallback first_itinerary_spot); camp / accommodation / course / experience ->
--   location = itinerary_spots[0]. Offers without a place get no row.
--
-- All *_months arrays: 12 values, January..December.
--   uv_months            mean DAILY MAXIMUM UV index, all-sky = typical midday UV
--   uv_clear_sky_months  same, cloud-free.  WHO: 0-2 low .. 11+ extreme
--                        CAMS global via Open-Meteo Air Quality API, hourly 2023-2025
--   air_temp_max_months  mean daily max air temperature 2 m, deg C
--   air_temp_min_months  mean daily min air temperature 2 m, deg C
--                        ERA5 via Open-Meteo Historical API, daily 2016-2025;
--                        elevation_m = elevation used for downscaling (NULL = terrain
--                        height at sample point; 0 = coastal override)
--   water_temp_months    mean sea surface temperature, deg C, Open-Meteo Marine API
--                        (nearest sea cell), hourly 2023-2025; NULL = no sea nearby
--
-- Refresh: pnpm cli climate-stats (weekly GitHub Action, .github/workflows/
-- climate-stats.yml) re-resolves every offer's point, fetches only cells not yet
-- cached, upserts offer_climate_stats and drops rows of offers that disappeared.
-- This migration also does a first fill for every offer whose point already has a
-- cached cell (nearest cell within 0.075 deg); the job fills the rest.
--
-- Safe to re-run: IF NOT EXISTS + upserts.
-- ============================================================

CREATE TABLE IF NOT EXISTS climate_points (
  lat10                 INTEGER NOT NULL,
  lng10                 INTEGER NOT NULL,
  sample_lat            DOUBLE PRECISION NOT NULL,   -- where the APIs were queried
  sample_lng            DOUBLE PRECISION NOT NULL,
  elevation_m           INTEGER,                     -- downscaling override for air temp (NULL = terrain)
  uv_months             NUMERIC(3,1)[] NOT NULL,
  uv_clear_sky_months   NUMERIC(3,1)[] NOT NULL,
  air_temp_max_months   NUMERIC(4,1)[] NOT NULL,
  air_temp_min_months   NUMERIC(4,1)[] NOT NULL,
  water_temp_months     NUMERIC(4,1)[],
  sources               TEXT NOT NULL DEFAULT 'UV: CAMS global via Open-Meteo Air Quality API 2023-2025; air temp: ERA5 via Open-Meteo Historical API 2016-2025; water temp: Open-Meteo Marine API SST 2023-2025',
  fetched_at            TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (lat10, lng10),
  CONSTRAINT climate_points_12_months CHECK (
    cardinality(uv_months) = 12 AND cardinality(uv_clear_sky_months) = 12
    AND cardinality(air_temp_max_months) = 12 AND cardinality(air_temp_min_months) = 12
    AND (water_temp_months IS NULL OR cardinality(water_temp_months) = 12))
);

CREATE TABLE IF NOT EXISTS climate_port_points (
  departure_port  TEXT NOT NULL,                 -- exactly as stored on the offer
  country         TEXT NOT NULL DEFAULT '',      -- offer country ('' if none)
  lat             DOUBLE PRECISION NOT NULL,
  lng             DOUBLE PRECISION NOT NULL,
  name            TEXT NOT NULL,                 -- resolved place name shown as point_name
  created_at      TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  PRIMARY KEY (departure_port, country)
);

CREATE TABLE IF NOT EXISTS offer_climate_stats (
  offer_id              UUID PRIMARY KEY,
  offer_table           TEXT NOT NULL CHECK (offer_table IN ('cruise_offers','package_offers')),
  offer_type            TEXT NOT NULL,         -- cruise | tour | camp | accommodation | course | experience
  point_basis           TEXT NOT NULL CHECK (point_basis IN ('departure_port','start_point','location','first_itinerary_spot')),
  point_name            TEXT,
  lat                   DOUBLE PRECISION NOT NULL,
  lng                   DOUBLE PRECISION NOT NULL,
  lat10                 INTEGER NOT NULL,
  lng10                 INTEGER NOT NULL,
  uv_months             NUMERIC(3,1)[] NOT NULL,
  uv_clear_sky_months   NUMERIC(3,1)[] NOT NULL,
  air_temp_max_months   NUMERIC(4,1)[] NOT NULL,
  air_temp_min_months   NUMERIC(4,1)[] NOT NULL,
  water_temp_months     NUMERIC(4,1)[],
  sources               TEXT NOT NULL,
  computed_at           TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  FOREIGN KEY (lat10, lng10) REFERENCES climate_points (lat10, lng10) ON UPDATE CASCADE
);

-- Same posture as every other table: RLS on, no policies (service role only).
ALTER TABLE climate_points      ENABLE ROW LEVEL SECURITY;
ALTER TABLE climate_port_points ENABLE ROW LEVEL SECURITY;
ALTER TABLE offer_climate_stats ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE climate_points      FROM anon, authenticated;
REVOKE ALL ON TABLE climate_port_points FROM anon, authenticated;
REVOKE ALL ON TABLE offer_climate_stats FROM anon, authenticated;

