-- First fill (the weekly job keeps it current).
WITH offers AS (
  SELECT 'cruise_offers'::text AS t, 'cruise'::text AS typ, offer_id, country, departure_port, itinerary_spots->0 AS s0
    FROM app_cruise_offer_cards
  UNION ALL
  SELECT 'package_offers', package_type, offer_id, country, departure_port, itinerary_spots->0
    FROM app_package_cards
), pts AS (
  SELECT o.offer_id, o.t, o.typ,
    CASE WHEN o.typ IN ('cruise','tour') AND p.departure_port IS NOT NULL
           THEN CASE o.typ WHEN 'cruise' THEN 'departure_port' ELSE 'start_point' END
         WHEN o.s0->>'lat' IS NOT NULL AND o.s0->>'lng' IS NOT NULL
           THEN CASE WHEN o.typ IN ('cruise','tour') THEN 'first_itinerary_spot' ELSE 'location' END
    END AS basis,
    CASE WHEN o.typ IN ('cruise','tour') AND p.departure_port IS NOT NULL THEN p.lat ELSE (o.s0->>'lat')::float8 END AS lat,
    CASE WHEN o.typ IN ('cruise','tour') AND p.departure_port IS NOT NULL THEN p.lng ELSE (o.s0->>'lng')::float8 END AS lng,
    CASE WHEN o.typ IN ('cruise','tour') AND p.departure_port IS NOT NULL THEN p.name ELSE o.s0->>'name' END AS name
  FROM offers o
  LEFT JOIN climate_port_points p ON p.departure_port = o.departure_port AND p.country = COALESCE(o.country, '')
)
INSERT INTO offer_climate_stats (offer_id, offer_table, offer_type, point_basis, point_name, lat, lng, lat10, lng10,
  uv_months, uv_clear_sky_months, air_temp_max_months, air_temp_min_months, water_temp_months, sources)
SELECT pts.offer_id, pts.t, pts.typ, pts.basis, pts.name, pts.lat, pts.lng, c.lat10, c.lng10,
  c.uv_months, c.uv_clear_sky_months, c.air_temp_max_months, c.air_temp_min_months, c.water_temp_months, c.sources
FROM pts
CROSS JOIN LATERAL (
  SELECT cp.* FROM climate_points cp
  WHERE abs(cp.lat10 / 10.0 - pts.lat) <= 0.075 AND abs(cp.lng10 / 10.0 - pts.lng) <= 0.075
  ORDER BY (cp.lat10 / 10.0 - pts.lat)^2 + (cp.lng10 / 10.0 - pts.lng)^2
  LIMIT 1
) c
WHERE pts.basis IS NOT NULL
ON CONFLICT (offer_id) DO UPDATE
  SET offer_table = EXCLUDED.offer_table, offer_type = EXCLUDED.offer_type,
      point_basis = EXCLUDED.point_basis, point_name = EXCLUDED.point_name,
      lat = EXCLUDED.lat, lng = EXCLUDED.lng, lat10 = EXCLUDED.lat10, lng10 = EXCLUDED.lng10,
      uv_months = EXCLUDED.uv_months, uv_clear_sky_months = EXCLUDED.uv_clear_sky_months,
      air_temp_max_months = EXCLUDED.air_temp_max_months, air_temp_min_months = EXCLUDED.air_temp_min_months,
      water_temp_months = EXCLUDED.water_temp_months, sources = EXCLUDED.sources,
      computed_at = NOW();

